examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
MonarchQueryBuilder(
    value = query,
    onValueChange = { query = it },
    fields = fields,
)
MonarchText(
    text = "Sample record (open, amount 120, flagged) " + if (query.matches(mapOf("status" to "open", "amount" to 120.0, "flagged" to true))) "matches." else "does not match.",
    style = MonarchTextStyle.Caption,
)
}

